.hr-ra-max:hover, .chr-parent:hover .hr-ra-max:hover       { border-radius: var(--ra-max);              }
.hr-ra-tl-max:hover, .chr-parent:hover .hr-ra-tl-max:hover { border-top-left-radius: var(--ra-max);     }
.hr-ra-tr-max:hover, .chr-parent:hover .hr-ra-tr-max:hover { border-top-right-radius: var(--ra-max);    }
.hr-ra-br-max:hover, .chr-parent:hover .hr-ra-br-max:hover { border-bottom-right-radius: var(--ra-max); }
.hr-ra-bl-max:hover, .chr-parent:hover .hr-ra-bl-max:hover { border-bottom-left-radius: var(--ra-max);  }